INSERT INTO public.site_content (id,section_key,title,subtitle,body,image_url,created_at,updated_at) VALUES ('c356c6e1-7469-46d4-947e-ae765de14aef','about_the_craft','The Craft',NULL,'In 2018, Linda received a single beaded necklace on her graduation day. It wasn''t just a gift it was a spark. That one bead carried the weight of centuries of African craftsmanship, the stories of hands that wove it, and the promise of something greater.
INSERT INTO public.site_content (id,section_key,title,subtitle,body,image_url,created_at,updated_at) VALUES ('6fef7d9c-577f-4b8e-a20d-f760bfd7f29e','the_chronicle_begins','The Chronicle Begins',NULL,'It started with one bead. A single beaded necklace, gifted to Linda on her graduation day in 2018. That moment sparked something  a deep connection to the craft, the culture, and the stories each bead carries.
